    def _replace_deadline_alert_records(
        cls,
        serialized_dag_id: UUID | None,
        uuid_mapping: dict[str, dict],
        session: Session = NEW_SESSION,
    ) -> None:
        """
        Replace the DeadlineAlert records for a serialized DAG that was updated in place.

        Used by the in-place update path (dynamic DAGs without task instances) where a new
        SerializedDagModel version is not created. Old records are deleted and new ones are
        created from ``uuid_mapping`` so they stay consistent with the serialized data.

        :param serialized_dag_id: The id of the SerializedDagModel that was updated.
        :param uuid_mapping: Mapping of UUID strings to deadline alert data dicts.
        :param session: Database session.
        """
        if serialized_dag_id is None:
            return

        existing_alerts = session.scalars(
            select(DeadlineAlertModel).where(DeadlineAlertModel.serialized_dag_id == serialized_dag_id)
        ).all()
        for alert in existing_alerts:
            session.delete(alert)
        session.flush()

        for uuid_str, deadline_data in uuid_mapping.items():
            session.add(
                DeadlineAlertModel(
                    id=UUID(uuid_str),
                    serialized_dag_id=serialized_dag_id,
                    reference=deadline_data[DeadlineAlertFields.REFERENCE],
                    interval=deadline_data[DeadlineAlertFields.INTERVAL],
                    callback_def=deadline_data[DeadlineAlertFields.CALLBACK],
                )
            )

